// Données de test (en prod, viennent de l'agent)
const input = $input.first().json;

const cas_usage_id = input.cas_usage_id ?? "cas_03";
const temps_actuel_minutes = parseFloat(input.temps_actuel_minutes ?? 120);
const frequence_par_semaine = parseFloat(input.frequence_par_semaine ?? 2);

// Constantes DEF Ouest
const taux_gain = 0.55;
const cout_horaire = 35;
const semaines_an = 45;

// Calculs
const temps_actuel_hebdo = temps_actuel_minutes * frequence_par_semaine;
const gain_hebdo_minutes = temps_actuel_hebdo * taux_gain;
const gain_annuel_heures = (gain_hebdo_minutes * semaines_an) / 60;
const gain_annuel_euros = gain_annuel_heures * cout_horaire;

return [{
  json: {
    cas_usage_id: cas_usage_id,
    gain_hebdo_minutes: Math.round(gain_hebdo_minutes),
    gain_annuel_heures: Math.round(gain_annuel_heures * 10) / 10,
    gain_annuel_euros: Math.round(gain_annuel_euros)
  }
}];
